{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "type": {
      "$ref": "functions.expression.IntegerInputSchemaType"
    },
    "description": {
      "description": "Human-readable description of the integer.",
      "type": [
        "string",
        "null"
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "type": [
        "integer",
        "null"
      ],
      "format": "int64"
    }
  },
  "required": [
    "type"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "oneOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "const": "text"
        }
      },
      "required": [
        "type",
        "text"
      ]
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "const": "image_url"
        }
      },
      "required": [
        "type",
        "image_url"
      ]
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "const": "input_audio"
        }
      },
      "required": [
        "type",
        "input_audio"
      ]
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "input_video"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        },
        "type": {
          "type": "string",
          "const": "video_url"
        }
      },
      "required": [
        "type",
        "video_url"
      ]
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "const": "file"
        }
      },
      "required": [
        "type",
        "file"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.RichContentExpression",
  "description": "Expression variant of [`RichContent`] for dynamic content.",
  "anyOf": [
    {
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "description": "Multi-part content expressions.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.WithExpression.agent.completions.message.RichContentPartExpression"
      }
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.SystemMessageExpression",
  "description": "Expression variant of [`SystemMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
      "$ref": "functions.expression.WithExpression.agent.completions.message.SimpleContentExpression"
    },
    "name": {
      "description": "Optional name expression.",
      "anyOf": [
        {
          "$ref": "functions.expression.WithExpression.Nullable_string"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "content"
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.AssistantToolCallExpression",
  "description": "Expression variant of [`AssistantToolCall`] for dynamic content.",
  "oneOf": [
    {
      "description": "A function call expression.",
      "type": "object",
      "properties": {
        "id": {
          "description": "The tool call ID expression.",
          "$ref": "functions.expression.WithExpression.string"
        },
        "function": {
          "description": "The function expression.",
          "$ref": "functions.expression.WithExpression.agent.completions.message.AssistantToolCallFunctionExpression"
        },
        "type": {
          "type": "string",
          "const": "function"
        }
      },
      "required": [
        "type",
        "id",
        "function"
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "functions.expression.WithExpression.Nullable_agent.completions.message.RichContentExpression",
  "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
  "anyOf": [
    {
      "description": "An expression (JMESPath or Starlark) to evaluate.",
      "$ref": "functions.expression.Expression"
    },
    {
      "description": "A literal value.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.RichContentExpression"
        },
        {
          "type": "null"
        }
      ]
    }
  ]
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "agent.completions.message.AssistantToolCallFunctionExpression",
  "description": "Expression variant of [`AssistantToolCallFunction`] for dynamic content.",
  "type": "object",
  "properties": {
    "name": {
      "description": "The function name expression.",
      "$ref": "functions.expression.WithExpression.string"
    },
    "arguments": {
      "description": "The arguments expression.",
      "$ref": "functions.expression.WithExpression.string"
    }
  },
  "required": [
    "name",
    "arguments"
  ]
}
